__global__ void matrix_mult_kernel(const float* A, const float* B, float* C, int N) {
    // Shared memory for tiles of A and B
    extern __shared__ float shared_mem[];
    float* tileA = shared_mem;
    float* tileB = &shared_mem[blockDim.x * blockDim.y];

    int tx = threadIdx.x;
    int ty = threadIdx.y;
    int row = blockIdx.y * blockDim.y + ty;
    int col = blockIdx.x * blockDim.x + tx;

    float sum = 0.0f;

    // Loop over tiles
    for (int t = 0; t < (N + blockDim.x - 1) / blockDim.x; t++) {
        // Load tile of A into shared memory
        int loadA_col = t * blockDim.x + tx;
        if (row < N && loadA_col < N) {
            tileA[ty * blockDim.x + tx] = A[row * N + loadA_col];
        } else {
            tileA[ty * blockDim.x + tx] = 0.0f;
