        int loadB_row = t * blockDim.y + ty;
        if (loadB_row < N && col < N) {
            tileB[ty * blockDim.x + tx] = B[loadB_row * N + col];
        } else {
            tileB[ty * blockDim.x + tx] = 0.0f;
        }

        __syncthreads();

        // Compute partial dot product
        for (int k = 0; k < blockDim.x; k++) {
            sum += tileA[ty * blockDim.x + k] * tileB[k * blockDim.x + tx];
        }

        __syncthreads();
    }

    // Write result to global memory
    if (row < N && col < N) {
