#include <cuda_runtime.h>

#define BLOCK_SIZE 16
#define TILE_SIZE 4

__global__ void matrix_mult_kernel(const float* A, const float* B, float* C, int N) {
    // Shared memory for tiles of A and B with padding to avoid bank conflicts
    __shared__ float tileA[BLOCK_SIZE][BLOCK_SIZE + 1];  // +1 padding
    __shared__ float tileB[BLOCK_SIZE][BLOCK_SIZE + 1];  // +1 padding

    int tx = threadIdx.x;
    int ty = threadIdx.y;

    int row = blockIdx.y * BLOCK_SIZE + ty;
    int col = blockIdx.x * BLOCK_SIZE + tx;

    // Register block for accumulating results
    float c[TILE_SIZE][TILE_SIZE] = {{0.0f}};

    // Loop over tiles
    for (int t = 0; t < (N + BLOCK_SIZE - 1) / BLOCK_SIZE; t++) {
        // Load tile of A into shared memory
        int loadA_col = t * BLOCK_SIZE + tx;
        if (row < N && loadA_col < N) {
            tileA[ty][tx] = A[row * N + loadA_col];
        } else {
            tileA[ty][tx] = 0.0f;
        }

        // Load tile of B into shared memory
        int loadB_row = t * BLOCK_SIZE + ty;
        if (loadB_row < N && col < N) {
            tileB[ty][tx] = B[loadB_row * N + col];
        } else {
            tileB[ty][tx] = 0.0f;
        }

        __syncthreads();

        // Compute partial dot product with loop unrolling
        for (int k = 0; k < BLOCK_SIZE; k++) {
            float a_val = tileA[ty][k];
            float b_val = tileB[k][tx];

            // Accumulate in registers
            #pragma unroll
            for (int i = 0; i < TILE_SIZE; i++) {
                #pragma unroll
                for (int j = 0; j < TILE_SIZE; j++) {
                    if ((ty*TILE_SIZE + i) < BLOCK_SIZE && (tx*TILE_SIZE + j) < BLOCK_SIZE) {
                        c[i][j] += a_val * b_val;
                    }
                }
            }
        }

        __syncthreads();
    }

    // Write result to global memory
    for (int i = 0; i < TILE_SIZE; i++) {
        for (int j = 0; j < TILE_SIZE; j++) {
            int out_row = row + i;
            int out_col = col + j;
            if (out_row < N && out_col < N) {
                C[out_row * N + out_col] = c[i][j];
            }
        }
    }
}

