    int col_block = blockIdx.x * BLOCK_SIZE;

    // Each thread computes TILE_SIZE x TILE_SIZE elements
    int row_start = row_block + ty * TILE_SIZE;
    int col_start = col_block + tx * TILE_SIZE;

